package service

import (
	"fmt"
	"sync"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// Service provides user-related business logic
type Service struct {
	users  map[string]User
	mutex  sync.RWMutex
	nextID int // Will be replaced by UUID
}

// NewService creates and returns a new Service instance
func NewService() *Service {
	return &Service{
		users:  make(map[string]User),
		nextID: 1,
	}
}

// CreateUser creates a new user
func (s *Service) CreateUser(u User) User {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	u.ID = fmt.Sprintf("%d", s.nextID) // Will be replaced by UUID
	s.nextID++
	s.users[u.ID] = u
	return u
}

// ListUsers returns all users
func (s *Service) ListUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// GetUser returns a user by ID
func (s *Service) GetUser(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"legacy_refactor/rep-2/internal/service"
)

// Handler handles HTTP requests
type Handler struct {
	service *service.Service
}

// NewHandler creates and returns a new Handler instance
func NewHandler(s *service.Service) *Handler {
	return &Handler{
		service: s,
	}
}

// ListUsersHandler handles GET /users requests
func (h *Handler) ListUsersHandler(w http.ResponseWriter, r *http.Request) {
	users := h.service.ListUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUserHandler handles POST /users requests
func (h *Handler) CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser := h.service.CreateUser(u)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserHandler handles GET /users/{id} requests
func (h *Handler) GetUserHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	u, ok := h.service.GetUser(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"legacy_refactor/rep-2/internal/api"
	"legacy_refactor/rep-2/internal/service"
)

func main() {
	svc := service.NewService()
	handler := api.NewHandler(svc)

	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			handler.ListUsersHandler(w, r)
		case http.MethodPost:
			handler.CreateUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			handler.GetUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

